fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants we actually consider:
    // if participations has fewer than n elements, use all.
    // else consider only first n.
    let limit = n.min(participations.len() as u8) as usize;

    // Count eligible participants, i.e., those with (5 - attendance_count) >= k
    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&attendance| 5u8.saturating_sub(attendance) >= k)
        .count();

    // The number of teams is the integer quotient of eligible_count by 3
    (eligible_count / 3) as u8
}